diff --git a/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs b/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs
index 74842c8..f4c4b14 100644
--- a/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs
+++ b/src/TaskTracker.Api/Endpoints/TaskEndpoints.cs
@@ -7,9 +7,9 @@ namespace TaskTracker.Api.Endpoints;
 /// CRUD endpoints for tasks, mounted under <c>/tasks</c>.
 /// </summary>
 /// <remarks>
-/// GET /tasks currently returns EVERY task, unfiltered. Closing that gap â€” adding optional
-/// <c>?status=</c> and <c>?priority=</c> filters â€” is the exercise the CHAOS worked example
-/// drives end-to-end. See <c>docs/demo/README.md</c>.
+/// GET /tasks takes an optional <c>?priority=</c> filter (filter-tasks-by-priority). The matching
+/// <c>?status=</c> filter, and combining the two with AND, remain the open half of that gap â€”
+/// see <c>docs/demo/README.md</c>.
 /// </remarks>
 public static class TaskEndpoints
 {
@@ -21,8 +21,22 @@ public static class TaskEndpoints
             .RequireAuthorization()
             .RequireRateLimiting(Policies.TaskRateLimit);

-        // GET /tasks â€” returns every task in the store. No filtering (yet).
-        group.MapGet("/", (TaskStore store) => Results.Ok(store.All()));
+        // GET /tasks â€” every task, or only those at ?priority= when the caller supplies one.
+        // Filtering happens here rather than in the store: the store stays a plain collection
+        // and query concerns stay on the HTTP side of the boundary.
+        group.MapGet("/", (string? priority, TaskStore store) =>
+        {
+            if (priority is null)
+                return Results.Ok(store.All());
+
+            if (TryMatchPriority(priority) is not { } match)
+                return Results.BadRequest(new
+                {
+                    error = $"Unknown priority. Accepted values: {string.Join(", ", Enum.GetNames<TaskPriority>())}."
+                });
+
+            return Results.Ok(store.All().Where(t => t.Priority == match).ToList());
+        });

         // GET /tasks/{id}
         group.MapGet("/{id:guid}", (Guid id, TaskStore store) =>
@@ -55,4 +69,20 @@ public static class TaskEndpoints

         return app;
     }
+
+    /// <summary>
+    /// The <see cref="TaskPriority"/> whose name equals <paramref name="value"/> ignoring case,
+    /// or <c>null</c> when the caller asked for something that is not a priority.
+    /// </summary>
+    /// <remarks>
+    /// Deliberately NOT <c>Enum.TryParse</c>: that accepts far more than the three names a caller
+    /// may legitimately send. It parses numeric strings ("2" â†’ High), accepts out-of-range numbers
+    /// ("7" â†’ an undefined value, still returning true), and ORs comma-separated lists together
+    /// ("Low,High" â†’ 0|2 â†’ High) even for an enum that is not [Flags]. Matching the declared names
+    /// explicitly is the only way the 400 contract actually holds.
+    /// </remarks>
+    private static TaskPriority? TryMatchPriority(string value) =>
+        Enum.GetValues<TaskPriority>()
+            .Cast<TaskPriority?>()
+            .FirstOrDefault(p => string.Equals(p!.Value.ToString(), value, StringComparison.OrdinalIgnoreCase));
 }
diff --git a/tests/TaskTracker.Tests/TaskEndpointsTests.cs b/tests/TaskTracker.Tests/TaskEndpointsTests.cs
index 6c4eb37..5475081 100644
--- a/tests/TaskTracker.Tests/TaskEndpointsTests.cs
+++ b/tests/TaskTracker.Tests/TaskEndpointsTests.cs
@@ -90,6 +90,115 @@ public class TaskEndpointsTests : IClassFixture<TestApiFactory>
         Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
     }

+    [Fact]
+    public async Task Get_tasks_with_high_priority_filter_returns_only_high_priority_tasks()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var tasks = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=High");
+
+        Assert.NotNull(tasks);
+        Assert.NotEmpty(tasks!);
+        Assert.All(tasks, t => Assert.Equal("High", t.Priority));
+        // Verify at least the two seeded High tasks
+        Assert.True(tasks.Count >= 2, "Expected at least 2 High priority tasks from seed data");
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_medium_priority_filter_returns_only_medium_priority_tasks()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var tasks = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Medium");
+
+        Assert.NotNull(tasks);
+        Assert.All(tasks, t => Assert.Equal("Medium", t.Priority));
+        // Seed has at least 1 Medium task
+        Assert.True(tasks.Count >= 1, "Expected at least 1 Medium priority task from seed data");
+    }
+
+    [Fact]
+    public async Task Get_tasks_without_priority_filter_returns_all_tasks()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var all = await client.GetFromJsonAsync<List<TaskDto>>("/tasks");
+        var high = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=High");
+        var medium = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Medium");
+        var low = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=Low");
+
+        Assert.NotNull(all);
+        Assert.NotEmpty(all!);
+        // The three filters partition the unfiltered list exactly: nothing the caller would have
+        // seen before is dropped when a filter is applied, and nothing is invented.
+        Assert.Equal(
+            all!.OrderBy(t => t.Id).ToList(),
+            high!.Concat(medium!).Concat(low!).OrderBy(t => t.Id).ToList());
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_case_insensitive_priority_filter()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var resultHigh = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=High");
+        var resultHIGH = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=HIGH");
+        var resulthigh = await client.GetFromJsonAsync<List<TaskDto>>("/tasks?priority=high");
+
+        Assert.Equal(resultHigh, resultHIGH);
+        Assert.Equal(resultHigh, resulthigh);
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_unrecognized_priority_returns_bad_request()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var response = await client.GetAsync("/tasks?priority=Urgent");
+
+        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
+        // Same error body shape the blank-title checks already use, and it names what IS accepted.
+        var body = await response.Content.ReadAsStringAsync();
+        Assert.Contains("\"error\"", body);
+        Assert.Contains("Low, Medium, High", body);
+        Assert.DoesNotContain("\"title\"", body);
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_numeric_priority_string_returns_bad_request()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var response2 = await client.GetAsync("/tasks?priority=2");
+        Assert.Equal(HttpStatusCode.BadRequest, response2.StatusCode);
+
+        var response7 = await client.GetAsync("/tasks?priority=7");
+        Assert.Equal(HttpStatusCode.BadRequest, response7.StatusCode);
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_empty_priority_parameter_returns_bad_request()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        var response = await client.GetAsync("/tasks?priority=");
+
+        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
+    }
+
+    [Fact]
+    public async Task Get_tasks_with_comma_separated_priority_returns_bad_request()
+    {
+        var client = _factory.CreateAuthenticatedClient();
+
+        // Enum.TryParse accepts comma-separated lists for ANY enum, not just [Flags] ones:
+        // "Low,High" ORs to 0|2 = High, and Enum.IsDefined then says it is a declared value.
+        // "Low,High" is not a priority name, so it must be rejected like any other bad input.
+        var response = await client.GetAsync("/tasks?priority=Low,High");
+
+        Assert.Equal(HttpStatusCode.BadRequest, response.StatusCode);
+    }
+
     /// <summary>Mirror of the API's task shape; enums arrive as strings ("Open", "High").</summary>
     internal record TaskDto(Guid Id, string Title, string Status, string Priority, DateTimeOffset CreatedAt);
 }
